import unreal
sysa=unreal.load_asset('/Game/SSPR_Validation/NS_SSPR_ProjTest')
print('SYSTEM_CLASS',sysa.get_class().get_path_name())
print('SYS_METHODS',[m for m in dir(sysa) if any(k in m.lower() for k in ['emitter','version','handle','script'])])
for p in ['emitter_handles','emitter_handles_internal','versioned_emitters','emitters']:
    try:
        v=sysa.get_editor_property(p)
        print('PROP',p,type(v).__name__,len(v) if hasattr(v,'__len__') else str(v))
        if hasattr(v,'__iter__'):
            for i,x in enumerate(v): print(' ITEM',i,type(x).__name__,str(x))
    except Exception as e: print('PROP_ERR',p,str(e)[:240])
print('DONE')
